import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.DyxC4IQh.js";const _=JSON.parse('{"title":"通知栏一键","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notification.md","filePath":"guide/notification.md","lastUpdated":1792178171000}'),n={name:"guide/notification.md"};function c(d,e,r,l,h,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="通知栏一键" tabindex="-1">通知栏一键 <a class="header-anchor" href="#通知栏一键" aria-label="Permalink to &quot;通知栏一键&quot;">​</a></h1><p>屏幕顶部弹出 heads-up 通知时，通知行的左上角会钉一个小角标，上面写着 <code>␣</code> 或 <code>⏎</code>，对应你在设置里选的通知键。按下那个键，等于点在那条通知上。</p><p>省掉的动作是：瞄一眼通知、伸手去戳屏幕顶部那条横幅。键盘接着打字的时候，这个动作特别打断节奏。</p><h2 id="什么算一条通知" tabindex="-1">什么算一条通知 <a class="header-anchor" href="#什么算一条通知" aria-label="Permalink to &quot;什么算一条通知&quot;">​</a></h2><p>判定条件全部满足才贴角标：</p><ul><li>窗口属于 SystemUI。</li><li>树里找到 <code>expandableNotificationRow</code>，也就是真正的通知行。</li><li>这一行对无障碍可见、高度大于 0，且顶边落在屏幕上方四分之一以内。</li><li>设备没有锁屏。</li><li>通知下拉面板没有拉开。</li></ul><p>拉下通知栏之后角标消失，因为这时候你已经在用手指操作，VimAct 不插手。音量条、亮度条那种系统弹窗没有通知行节点，走的是同一套窗口但不会被认成通知，按通知键不会误触发。</p><h2 id="按下之后" tabindex="-1">按下之后 <a class="header-anchor" href="#按下之后" aria-label="Permalink to &quot;按下之后&quot;">​</a></h2><p>通知键触发的是通知行自己的点击行为，在 AOSP 上就是打开这条通知对应的应用。VimAct 只负责把那一下点准，不接管通知内容，也不做展开、回复、清除这些操作。</p><p>角标的增删由 SystemUI 发来的无障碍事件驱动，16 毫秒内的事件合并成一次刷新。通知还在就贴着它，通知消失后下一条 SystemUI 事件到达时角标撤掉；进入 hint 模式期间既不刷新也会先收起，退出 hint 模式后恢复。</p><h2 id="hint-模式内不生效" tabindex="-1">hint 模式内不生效 <a class="header-anchor" href="#hint-模式内不生效" aria-label="Permalink to &quot;hint 模式内不生效&quot;">​</a></h2><p>进入 hint 模式后，通知角标会收起，通知键不再响应。原因是 hint 模式是模态的，所有按键都归输入缓冲和光标使用。被排除的应用同样不响应这个键，两者与角标之间的具体关系见<a href="/vimact-site/guide/settings.html">设置</a>一节。</p><p>这里有一个键位重叠要留意：通知键和光标点击键默认都是 <code>Space</code>。非 hint 模式下同时存在光标和通知时，<code>Space</code> 优先点光标，其次是点通知。想让两者互不干扰，把光标点击键改成 <code>Enter</code>，通知键留 <code>Space</code>。</p>',13)])])}const m=a(n,[["render",c]]);export{_ as __pageData,m as default};
